export const getAssetPath = (type, name) => {
  if (name.startsWith('http')) {
    return name;
  }
  if (process.env.NODE_ENV === 'production') {
    const fileName = localAssets[type][name].split('/').pop();
    return `${ASSET_BASE_URL_S3}/${type}/${fileName}`;
  }
  return localAssets[type][name];
};
