import React, { useState, useEffect } from 'react';
import { Play, Pause, Volume2, Volume1, Volume, VolumeX } from 'lucide-react';

const VolumeControl = ({ isPlaying, volume, onPlayPause, onVolumeChange, sectionTheme }) => {
  const [showPlayText, setShowPlayText] = useState(false);

  useEffect(() => {
    const hasVisited = localStorage.getItem('hasVisited');
    if (!hasVisited) {
      setShowPlayText(true);
      localStorage.setItem('hasVisited', 'true');
    }
  }, []);

  const handlePlayPause = () => {
    setShowPlayText(false);
    onPlayPause();
  };

  const getVolumeIcon = () => {
    const iconProps = { size: 20, color: sectionTheme.primary, className: 'transition-colors duration-300' };
    if (volume === 0) return <VolumeX {...iconProps} />;
    if (volume < 0.33) return <Volume {...iconProps} />;
    if (volume < 0.66) return <Volume1 {...iconProps} />;
    return <Volume2 {...iconProps} />;
  };

  const dynamicStyles = {
    '--theme-color': sectionTheme.primary,
    '--theme-secondary': sectionTheme.secondary,
    '--theme-glow-color': `rgba(${sectionTheme.primaryRgb}, 0.6)`,
  };

  return (
    <>
      <style>
        {`
          @keyframes spinner-rotate {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
          @keyframes subtle-pulse {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.05); }
          }
          .play-spinner-wrapper {
            position: relative;
            width: 64px; /* w-16 */
            height: 64px; /* h-16 */
          }
          .play-spinner-wrapper::before {
            content: "";
            position: absolute;
            z-index: -1;
            top: -5px;
            left: -5px;
            right: -5px;
            bottom: -5px;
            border-radius: 50%;
          }
          .play-spinner-wrapper.is-animating::before {
            background: conic-gradient(
              #f97316, #ec4899, #8b5cf6, #3b82f6, #14b8a6, #f97316
            );
            filter: blur(8px);
            animation: spinner-rotate 2s linear infinite;
          }
          .play-spinner-wrapper.is-animating button {
            animation: subtle-pulse 2s ease-in-out infinite;
          }
          @keyframes fade-in-up {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
          }
          .volume-slider::-webkit-slider-thumb {
            background-color: var(--theme-color);
          }
          .volume-slider::-moz-range-thumb {
            background-color: var(--theme-color);
          }
        `}
      </style>
      <div className="flex flex-col items-center space-y-3" style={dynamicStyles}>
        {/* Вертикальный слайдер появляется только при проигрывании */}
        <div className={`relative flex justify-center w-10 h-28 transition-opacity duration-300 ${isPlaying ? 'opacity-100' : 'opacity-0'}`}>
          <div className="relative w-1.5 h-full bg-white/30 backdrop-blur-sm rounded-full overflow-hidden">
            <div 
              className="absolute bottom-0 w-full transition-all duration-100 rounded-full"
              style={{ 
                height: `${volume * 100}%`,
                backgroundColor: 'var(--theme-color)',
              }}
            ></div>
          </div>
          <input
            type="range"
            min="0"
            max="1"
            step="0.01"
            value={volume}
            onChange={(e) => onVolumeChange(parseFloat(e.target.value))}
            className="volume-slider absolute w-28 h-1.5 top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 -rotate-90 appearance-none cursor-pointer bg-transparent focus:outline-none
                       [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-5 [&::-webkit-slider-thumb]:h-5 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:shadow-lg [&::-webkit-slider-thumb]:cursor-pointer
                       [&::-moz-range-thumb]:appearance-none [&::-moz-range-thumb]:w-5 [&::-moz-range-thumb]:h-5 [&::-moz-range-thumb]:rounded-full [&::-moz-range-thumb]:shadow-lg [&::-moz-range-thumb]:cursor-pointer"
          />
        </div>

        {/* Главная кнопка Play/Pause */}
        <div className="relative flex flex-col items-center">
          {showPlayText && (
            <div 
              className="mb-2 bg-gray-800 text-white text-sm px-3 py-1 rounded-lg shadow-lg whitespace-nowrap"
              style={{ animation: 'fade-in-up 0.5s ease-out' }}
            >
              Прослушать
            </div>
          )}
          <div className={`play-spinner-wrapper ${!isPlaying ? 'is-animating' : ''}`}>
            <button
              onClick={handlePlayPause}
              className="w-16 h-16 flex items-center justify-center rounded-full text-white transition-all duration-300 ease-in-out hover:bg-opacity-100 active:scale-95 shadow-lg"
              style={{ 
                backgroundColor: sectionTheme.primary,
                boxShadow: `0 0 15px 3px var(--theme-glow-color)`,
              }}
              aria-label={isPlaying ? "Пауза" : "Воспроизвести"}
            >
              {isPlaying ? <Pause size={36} color="white" /> : <Play size={36} color="white" fill="white" />}
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default VolumeControl;
