import React, { useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import ReactGA from 'react-ga4';
import TensisTechWebsite from './components/TensoraWebsite';
import Bitrix24Page from './pages/Bitrix24Page';
import SMMPage from './pages/SMMPage';
import AIIntegrationPage from './pages/AIIntegrationPage';
import WebsiteCreationPage from './pages/WebsiteCreationPage';
import GoldcontainerPage from './pages/GoldcontainerPage';
import OrganixstylePage from './pages/OrganixstylePage';
import SweetDreamsPage from './pages/SweetDreamsPage';

const TRACKING_ID = process.env.REACT_APP_GA_MEASUREMENT_ID;
if (TRACKING_ID) {
  ReactGA.initialize(TRACKING_ID);
}

function usePageViews() {
  const location = useLocation();
  useEffect(() => {
    if (TRACKING_ID) {
      ReactGA.send({ hitType: "pageview", page: location.pathname + location.search });
    }
  }, [location]);
}

function App() {
  usePageViews();

  return (
      <Routes>
        <Route path="/" element={<TensisTechWebsite />} />
        <Route path="/services/bitrix24" element={<Bitrix24Page />} />
        <Route path="/services/smm" element={<SMMPage />} />
        <Route path="/services/ai-integration" element={<AIIntegrationPage />} />
        <Route path="/services/website-creation" element={<WebsiteCreationPage />} />
        <Route path="/cases/goldcontainer" element={<GoldcontainerPage />} />
        <Route path="/cases/organixstyle" element={<OrganixstylePage />} />
        <Route path="/cases/sweetdreams" element={<SweetDreamsPage />} />
      </Routes>
  );
}

export default () => (
  <Router>
    <App />
  </Router>
);
