import { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';

const usePageTransition = (duration = 2000) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const location = useLocation();
  const isFirstLoad = useRef(true);

  // Обработка начальной загрузки страницы
  useEffect(() => {
    if (isFirstLoad.current) {
      const timer = setTimeout(() => {
        setIsLoading(false);
        isFirstLoad.current = false;
      }, duration);

      return () => clearTimeout(timer);
    }
  }, [duration]);

  // Обработка переходов между страницами
  useEffect(() => {
    if (!isFirstLoad.current) {
      // Показываем лоудер при смене маршрута только после первоначальной загрузки
      setIsTransitioning(true);
      
      // Сбрасываем позицию прокрутки к началу страницы с плавной анимацией
      window.scrollTo({
        top: 0,
        left: 0,
        behavior: 'smooth'
      });
      
      const transitionTimer = setTimeout(() => {
        setIsTransitioning(false);
      }, duration);

      return () => clearTimeout(transitionTimer);
    }
  }, [location.pathname, duration]);

  return {
    isLoading,
    isTransitioning,
    showLoader: isLoading || isTransitioning
  };
};

export default usePageTransition; 