import React from 'react';
import { useNavigate } from 'react-router-dom';
import { ReactComponent as LogoIcon } from '../assets/img/logo.svg';

const ServicesSection = ({ sectionTheme, getBackdropStyle, onNavigate, highlightedService }) => {
  const navigate = useNavigate();
  
  const handleServiceClick = (serviceIndex) => {
    const routes = [
      '/services/bitrix24',
      '/services/smm', 
      '/services/ai-integration',
      '/services/website-creation'
    ];
    
    if (onNavigate) {
      onNavigate(routes[serviceIndex]);
    } else {
      navigate(routes[serviceIndex]);
    }
  };

  const services = [
    {
      id: 'b24',
      title: "Битрикс24",
      subtitle: "Делаем Битрикс24 удобным и эффективным",
      description: "Настройка, доработка и техническая поддержка. Автоматизируем рутину, строим прозрачные воронки продаж и обучаем вашу команду.",
      buttonText: "Узнать больше о Битрикс24",
      color: `from-purple-500 to-pink-500`,
      iconColor: '#8b5cf6'
    },
    {
      id: 'smm',
      title: "SMM и Контент",
      subtitle: "Привлекаем клиентов из социальных сетей",
      description: "Создаем контент, который продает. От ведения страниц и таргетированной рекламы до съемки вирусных роликов (Reels, Shorts).",
      buttonText: "Узнать больше о SMM",
      color: `from-orange-500 to-red-500`,
      iconColor: '#f97316'
    },
    {
      id: 'ai',
      title: "Внедрение AI",
      subtitle: "Автоматизируем рутину с помощью ИИ",
      description: "Разрабатываем умных чат-ботов для сайта, автоматизируем поддержку и персонализируем клиентский опыт с помощью нейросетей.",
      buttonText: "Узнать больше об AI",
      color: `from-teal-500 to-cyan-500`,
      iconColor: '#14b8a6'
    },
    {
      id: 'website',
      title: "Создание сайтов",
      subtitle: "Разрабатываем сайты, которые работают на вас",
      description: "От лендингов и корпоративных сайтов до сложных интернет-магазинов. Создаем быстрые, адаптивные и готовые к SEO-продвижению сайты.",
      buttonText: "Узнать больше о создании сайтов",
      color: `from-blue-500 to-indigo-500`,
      iconColor: '#3b82f6'
    }
  ];

  const sortedServices = [...services].sort((a, b) => {
    if (a.id === highlightedService) return -1;
    if (b.id === highlightedService) return 1;
    return 0;
  });

  return (
  <section id="services" className="py-16 sm:py-20 bg-transparent">
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <h2 className={`font-heading text-3xl sm:text-4xl lg:text-4xl font-bold text-center mb-12 sm:mb-16 bg-gradient-to-r ${sectionTheme.textGradient} bg-clip-text text-transparent`}>
        В чем мы вам поможем?
      </h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 sm:gap-8">
        {sortedServices.map((service) => (
          <div 
            key={service.id} 
            className={`relative group h-full transition-all duration-500 ${service.id === highlightedService ? 'transform scale-105' : ''}`}
          >
            <div 
              className={`relative p-6 sm:p-8 h-full rounded-2xl shadow-xl transform transition-all duration-300 backdrop-blur-lg bg-white/5 border border-white/10`}
              style={getBackdropStyle ? getBackdropStyle(sectionTheme, 'card') : {}}
            >
              <div className="flex flex-col h-full">
                <div className={`inline-flex items-center justify-center w-12 h-12 rounded-xl bg-gradient-to-r ${service.color} mb-4`}>
                  <LogoIcon 
                    className="w-7 h-7"
                    style={{
                      color: 'white',
                      filter: `drop-shadow(0 2px 4px rgba(0,0,0,0.2))`
                    }}
                  />
                </div>
                
                <h3 
                  className={`font-heading text-xl sm:text-2xl font-bold mb-2 transition-all duration-300 ${service.id === highlightedService ? 'text-white' : `bg-gradient-to-r ${sectionTheme.textGradient} bg-clip-text text-transparent`}`}
                  style={service.id === highlightedService ? { textShadow: `0 0 10px rgba(${sectionTheme.primaryRgb}, 0.8)` } : {}}
                >
                  {service.title}
                </h3>
                
                <h4 className="font-heading text-base sm:text-lg font-semibold mb-4 text-white">
                  {service.subtitle}
                </h4>
                
                <p className="font-body text-gray-300 mb-6 flex-grow text-sm sm:text-base leading-relaxed">
                  {service.description}
                </p>
                
                <button
                  onClick={() => handleServiceClick(services.findIndex(s => s.id === service.id))}
                  className={`w-full py-3 px-4 rounded-lg font-semibold text-white transition-all duration-300 bg-gradient-to-r ${service.color} hover:shadow-lg text-sm sm:text-base relative overflow-hidden group/btn`}
                >
                  <span className="relative z-10">{service.buttonText}</span>
                  <div className="absolute inset-0 bg-gradient-to-r from-white/20 to-transparent transform -skew-x-12 -translate-x-full group-hover/btn:translate-x-full transition-transform duration-700 ease-out"></div>
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  </section>
  );
};

export default ServicesSection; 