import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import VideoBackground from '../components/VideoBackground';
import FooterSection from '../components/FooterSection';
import Logo from '../components/Logo';
import LoadingAnimation from '../components/LoadingAnimation';
import usePageTransition from '../hooks/usePageTransition';
import VolumeControl from '../components/VolumeSlider';
import FloatingActionButton from '../components/FloatingActionButton';
import useResponsivePosition from '../hooks/useResponsivePosition';
import ContactSection from '../components/ContactSection';
import { getAssetPath } from '../config';

import { scrollToSection } from '../utils/scroll';

const initialPosition = [25, 0, 0];
const responsiveCoefficients = { mobileCoefficient: 0.1, desktopCoefficient: 0.5 };

const ServiceLayout = ({ children, sectionTheme, title, pageTitle, pageDescription, videoSrc }) => {
  const { showLoader } = usePageTransition(2000);
  const [volume, setVolume] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  const handlePlayPause = () => {
    setIsPlaying(!isPlaying);
    if (!isPlaying && volume === 0) {
      setVolume(0.5);
    }
  };

  const handleVolumeChange = (newVolume) => {
    const safeVolume = (typeof newVolume === 'number' && isFinite(newVolume)) ? newVolume : 0;
    const clampedVolume = Math.max(0, Math.min(1, safeVolume));
    setVolume(clampedVolume);
    if (clampedVolume > 0 && !isPlaying) {
      setIsPlaying(true);
    }
  };

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const videoPosition = useResponsivePosition(initialPosition, responsiveCoefficients);

  const getBackdropStyle = (sectionTheme, variant = 'default') => {
    const baseStyle = {
      backdropFilter: 'blur(16px)',
      WebkitBackdropFilter: 'blur(16px)',
      border: '1px solid rgba(255, 255, 255, 0.1)',
      borderRadius: '12px',
    };

    switch (variant) {
      case 'card':
        return {
          ...baseStyle,
          background: `linear-gradient(135deg, 
            rgba(255, 255, 255, 0.08) 0%,
            rgba(255, 255, 255, 0.04) 50%,
            rgba(255, 255, 255, 0.02) 100%),
            linear-gradient(135deg,
            rgba(${sectionTheme.primaryRgb}, 0.06) 0%,
            rgba(${sectionTheme.primaryRgb}, 0.02) 100%)`
        };
      default:
        return {
          ...baseStyle,
          background: `linear-gradient(135deg, 
            rgba(255, 255, 255, 0.08) 0%,
            rgba(255, 255, 255, 0.04) 50%,
            rgba(255, 255, 255, 0.02) 100%)`
        };
    }
  };

  return (
    <>
      <VideoBackground 
        videoSrc={videoSrc || getAssetPath('video', 'services')}
        position={videoPosition}
        volume={volume}
        isPlaying={isPlaying}
      />
      
      <div className="min-h-screen bg-transparent text-white overflow-x-hidden relative z-10">
        {/* Навигация */}
        <nav className="fixed top-0 left-0 right-0 z-50 bg-gray-900/80 backdrop-blur-sm border-b border-gray-800">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              {/* Logo */}
              <div className="flex items-center">
                <Link to="/">
                  <Logo
                    logoText="TensisTech"
                    sectionTheme={sectionTheme}
                    size="normal"
                  />
                </Link>
              </div>

              {/* Меню */}
              <div className="hidden md:flex items-center space-x-6">
                <Link 
                  to="/"
                  className="text-gray-300 hover:text-white transition-colors px-3 py-2 rounded-md text-sm font-medium"
                >
                  Главная
                </Link>
                <Link 
                  to="/#services" 
                  className="text-gray-300 hover:text-white transition-colors px-3 py-2 rounded-md text-sm font-medium"
                >
                  Услуги
                </Link>
                <Link 
                  to="/#contact" 
                  className="text-gray-300 hover:text-white transition-colors px-3 py-2 rounded-md text-sm font-medium"
                >
                  Контакты
                </Link>
              </div>

              {/* Мобильное меню */}
              <div className="md:hidden">
                <Link 
                  to="/" 
                  className="text-gray-300 hover:text-white transition-colors"
                >
                  Назад
                </Link>
              </div>
            </div>
          </div>
        </nav>

        {/* Основной контент */}
        <main className="pt-16">
          {children}
        </main>

        <ContactSection 
          id="contact"
          sectionTheme={sectionTheme}
          getBackdropStyle={getBackdropStyle}
        />

        {/* Футер */}
        <FooterSection 
          sectionTheme={sectionTheme}
          getBackdropStyle={getBackdropStyle}
        />

        <div className="fixed bottom-8 right-5 flex flex-col items-center space-y-4 z-40">
          <VolumeControl isPlaying={isPlaying} volume={volume} onPlayPause={handlePlayPause} onVolumeChange={handleVolumeChange} sectionTheme={sectionTheme} />
          <FloatingActionButton scrollToSection={scrollToSection} />
        </div>
      </div>

      {/* Индикатор загрузки */}
      {showLoader && (
        <LoadingAnimation 
          theme="service" 
          subtitle="Загружаем сервисы..." 
        />
      )}
    </>
  );
};

export default ServiceLayout; 