import React, { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import Logo from './Logo';

const Navigation = ({ scrollToSection, activeSection, sectionTheme }) => {
  const [logoText, setLogoText] = useState('TensisTech');
  const [isAnimating, setIsAnimating] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const mobileMenuRef = useRef(null);
  const location = useLocation();

  useEffect(() => {
    const interval = setInterval(() => {
      setIsAnimating(true);
      
      setTimeout(() => {
        setLogoText(prev => prev === 'TensisTech' ? 'ТензисТех' : 'TensisTech');
        setIsAnimating(false);
      }, 300);
    }, 8000);

    return () => clearInterval(interval);
  }, []);

  // Close mobile menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (mobileMenuRef.current && !mobileMenuRef.current.contains(event.target)) {
        setIsMobileMenuOpen(false);
      }
    };

    if (isMobileMenuOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      document.addEventListener('touchstart', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('touchstart', handleClickOutside);
    };
  }, [isMobileMenuOpen]);

  // Close mobile menu on scroll
  useEffect(() => {
    const handleScroll = () => {
      if (isMobileMenuOpen) {
        setIsMobileMenuOpen(false);
      }
    };

    if (isMobileMenuOpen) {
      window.addEventListener('scroll', handleScroll);
    }

    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, [isMobileMenuOpen]);

  const handleMobileMenuToggle = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  const handleMenuClick = (item) => {
    if (item.route) {
      window.location.href = item.route;
    } else {
      if (location.pathname !== '/') {
        window.location.href = `/#${item.id}`;
      } else {
        scrollToSection(item.id);
      }
    }
  };

  const handleMobileMenuClick = (item) => {
    handleMenuClick(item);
    setIsMobileMenuOpen(false);
  };

  const menuItems = [
    { id: 'hero', label: 'Главная' },
    { id: 'services', label: 'Услуги' },
    { id: 'about', label: 'О нас' },
    { id: 'contact', label: 'Контакты' }
  ];

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 bg-gray-900/80 backdrop-blur-sm border-b border-gray-800" ref={mobileMenuRef}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <div className="flex items-center">
            <Logo
              logoText={logoText}
              sectionTheme={sectionTheme}
              size="normal"
              className={`transition-all duration-300 ${
                isAnimating ? 'opacity-0 scale-95 blur-sm' : 'opacity-100 scale-100 blur-0'
              }`}
            />
          </div>

          {/* Desktop Menu */}
          <div className="hidden md:block">
            <div className="ml-10 flex items-baseline space-x-6 lg:space-x-8">
              {menuItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleMenuClick(item)}
                  className={`px-3 py-2 rounded-md text-sm font-medium transition-all duration-150 ease-out ${
                    activeSection === item.id
                      ? `text-white shadow-lg`
                      : 'text-gray-300 hover:text-white hover:bg-gray-700 hover:scale-105 hover:shadow-md'
                  }`}
                  style={activeSection === item.id ? {
                    background: `linear-gradient(135deg, ${sectionTheme.primary}, ${sectionTheme.secondary})`,
                    boxShadow: `0 4px 20px rgba(${sectionTheme.primaryRgb}, 0.3)`
                  } : {}}
                >
                  {item.label}
                </button>
              ))}
            </div>
          </div>

          {/* Mobile menu button */}
          <div className="md:hidden">
            <button
              onClick={handleMobileMenuToggle}
              className="inline-flex items-center justify-center p-2 rounded-md text-gray-400 hover:text-white hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-inset transition-all duration-300"
              style={{
                '--tw-ring-color': sectionTheme.primary
              }}
              aria-expanded={isMobileMenuOpen}
              aria-label="Открыть главное меню"
            >
              {/* Animated Hamburger Icon */}
              <div className="w-6 h-6 flex flex-col justify-center items-center">
                <span 
                  className={`block h-0.5 w-6 bg-current transform transition duration-300 ease-in-out ${
                    isMobileMenuOpen ? 'rotate-45 translate-y-1.5' : ''
                  }`}
                  style={{ backgroundColor: isMobileMenuOpen ? sectionTheme.primary : 'currentColor' }}
                ></span>
                <span 
                  className={`block h-0.5 w-6 bg-current transform transition duration-300 ease-in-out mt-1 ${
                    isMobileMenuOpen ? 'opacity-0' : ''
                  }`}
                ></span>
                <span 
                  className={`block h-0.5 w-6 bg-current transform transition duration-300 ease-in-out mt-1 ${
                    isMobileMenuOpen ? '-rotate-45 -translate-y-1.5' : ''
                  }`}
                  style={{ backgroundColor: isMobileMenuOpen ? sectionTheme.primary : 'currentColor' }}
                ></span>
              </div>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      <div className={`md:hidden transition-all duration-300 ease-in-out ${
        isMobileMenuOpen ? 'max-h-80 opacity-100' : 'max-h-0 opacity-0'
      } overflow-hidden`}>
        <div 
          className="px-2 pt-2 pb-3 space-y-1 sm:px-3 border-t border-gray-700"
          style={{
            background: `linear-gradient(135deg, 
              rgba(17, 24, 39, 0.95) 0%,
              rgba(31, 41, 55, 0.90) 100%),
              linear-gradient(135deg,
              rgba(${sectionTheme.primaryRgb}, 0.05) 0%,
              rgba(${sectionTheme.primaryRgb}, 0.02) 100%)`,
            backdropFilter: 'blur(16px)',
            WebkitBackdropFilter: 'blur(16px)'
          }}
        >
          {menuItems.map((item, index) => (
            <button
              key={item.id}
              onClick={() => handleMobileMenuClick(item)}
              className={`block w-full text-left px-3 py-2 rounded-md text-base font-medium transition-all duration-150 ease-out transform ${
                activeSection === item.id
                  ? 'text-white shadow-lg scale-105'
                  : 'text-gray-300 hover:text-white hover:bg-gray-700 hover:scale-105 hover:shadow-md'
              }`}
              style={{
                ...(activeSection === item.id ? {
                  background: `linear-gradient(135deg, ${sectionTheme.primary}, ${sectionTheme.secondary})`,
                  boxShadow: `0 4px 20px rgba(${sectionTheme.primaryRgb}, 0.3)`
                } : {}),
                transitionDelay: `${index * 50}ms`
              }}
            >
              {item.label}
            </button>
          ))}
        </div>
      </div>
    </nav>
  );
};

export default Navigation; 