import React, { useState, useEffect, useMemo, useRef } from 'react';
import VideoBackground from './VideoBackground';
import HeroSection from './HeroSection.js';
import ServicesSection from './ServicesSection';
import CasesSection from './CasesSection';
import AboutSection from './AboutSection';
import ContactSection from './ContactSection';
import FooterSection from './FooterSection';
import Navigation from './Navigation';
import FloatingActionButton from './FloatingActionButton';
import LoadingAnimation from './LoadingAnimation';
import NavigationWithLoader from './NavigationWithLoader';
import usePageTransition from '../hooks/usePageTransition';
import usePageMetadata from '../hooks/usePageMetadata';
import useResponsivePosition from '../hooks/useResponsivePosition';
import VolumeControl from './VolumeSlider';
import { getAssetPath } from '../config';

const PARTICLE_SETTINGS = {
  hero: { video: getAssetPath('video', 'welcome'), morphingParticlePosition: [25, 0, 0] },
  services: { video: getAssetPath('video', 'services'), morphingParticlePosition: [25, -5, 0] },
  cases: { video: getAssetPath('video', 'cases'), morphingParticlePosition: [-25, 0, 0] },
  process: { video: getAssetPath('video', 'welcome'), morphingParticlePosition: [-25, 0, 0] },
  about: { video: getAssetPath('video', 'about'), morphingParticlePosition: [25, 0, 0] },
  contact: { video: getAssetPath('video', 'contact'), morphingParticlePosition: [-25, 0, 0] },
  default: { video: getAssetPath('video', 'welcome'), morphingParticlePosition: [25, 0, 0] },
};

const SECTION_THEMES = {
  hero: { primary: '#3b82f6', primaryRgb: '59, 130, 246', secondary: '#38bdf8', textGradient: 'from-sky-400 via-blue-500 to-indigo-500' },
  services: { primary: '#7ec99c', primaryRgb: '126, 201, 156', secondary: '#9dd4b5', textGradient: 'from-green-300 to-emerald-300' },
  cases: { primary: '#f7c97e', primaryRgb: '247, 201, 126', secondary: '#fad49a', textGradient: 'from-orange-300 to-amber-300' },
  process: { primary: '#f7c97e', primaryRgb: '247, 201, 126', secondary: '#fad49a', textGradient: 'from-orange-300 to-amber-300' },
  about: { primary: '#60c5ba', primaryRgb: '96, 197, 186', secondary: '#7dd3c0', textGradient: 'from-teal-300 to-cyan-300' },
  contact: { primary: '#98b3f0', primaryRgb: '152, 179, 240', secondary: '#b8caf7', textGradient: 'from-indigo-300 to-blue-300' },
  default: { primary: '#7db3f0', primaryRgb: '125, 179, 240', secondary: '#a8c8f5', textGradient: 'from-blue-300 via-indigo-300 to-blue-400' },
};

const TensisTechWebsite = ({ onNavigate }) => {
  usePageMetadata(
    "TensisTech | Автоматизация бизнеса, SMM и AI-решения",
    "Повышаем эффективность вашего бизнеса с помощью интеграции Битрикс24, SMM-продвижения и внедрения AI-технологий."
  );

  const [activeSection, setActiveSection] = useState('hero');
  const [highlightedService, setHighlightedService] = useState(null);
  const { showLoader } = usePageTransition(2000);
  const [volume, setVolume] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const isScrollingRef = useRef(false);
  const scrollTimeoutRef = useRef(null);

  const handlePlayPause = () => {
    setIsPlaying(!isPlaying);
    if (!isPlaying && volume === 0) {
      setVolume(0.5);
    }
  };

  const handleVolumeChange = (newVolume) => {
    const safeVolume = (typeof newVolume === 'number' && isFinite(newVolume)) ? newVolume : 0;
    const clampedVolume = Math.max(0, Math.min(1, safeVolume));
    setVolume(clampedVolume);
    if (clampedVolume > 0 && !isPlaying) {
      setIsPlaying(true);
    }
  };

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      isScrollingRef.current = true;
      clearTimeout(scrollTimeoutRef.current);

      element.scrollIntoView({ behavior: 'smooth' });
      setActiveSection(sectionId);
      if (window.history.pushState) {
        window.history.pushState(null, null, `#${sectionId}`);
      } else {
        window.location.hash = sectionId;
      }

      scrollTimeoutRef.current = setTimeout(() => {
        isScrollingRef.current = false;
      }, 1000);
    }
  };

  useEffect(() => {
    const handleScroll = () => {
      if (isScrollingRef.current) return;
      const sections = ['hero', 'services', 'cases', 'about', 'contact'];
      const scrollPosition = window.scrollY + window.innerHeight / 2;
      for (const section of sections) {
        const element = document.getElementById(section);
        if (element && scrollPosition >= element.offsetTop && scrollPosition < element.offsetTop + element.offsetHeight) {
          setActiveSection(section);
          break;
        }
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearTimeout(scrollTimeoutRef.current);
    }
  }, []);

  useEffect(() => {
    if (!showLoader) {
      const hash = window.location.hash.substring(1);
      if (hash) {
        setTimeout(() => {
          scrollToSection(hash);
        }, 100);
      }
    }
  }, [showLoader]);

  useEffect(() => {
    const videoUrls = [...new Set(Object.values(PARTICLE_SETTINGS).map(s => s.video))];
    videoUrls.forEach(url => {
      const link = document.createElement('link');
      link.rel = 'preload';
      link.as = 'video';
      link.href = url;
      link.crossOrigin = 'anonymous';
      document.head.appendChild(link);
    });
  }, []);

  const getParticleSettings = (section) => PARTICLE_SETTINGS[section] || PARTICLE_SETTINGS.default;
  const getSectionTheme = (section) => SECTION_THEMES[section] || SECTION_THEMES.default;

  const particleSettings = getParticleSettings(activeSection);
  const sectionTheme = getSectionTheme(activeSection);
  const videoPosition = useResponsivePosition(particleSettings.morphingParticlePosition, {
    mobileCoefficient: 0.1,
    desktopCoefficient: 0.5
  });

  const getBackdropStyle = (theme, variant = 'default') => {
    const baseStyle = { backdropFilter: 'blur(5px)', WebkitBackdropFilter: 'blur(5px)', border: '1px solid rgba(255, 255, 255, 0.05)', borderRadius: '12px' };
    if (variant === 'card') {
      return { ...baseStyle, background: `linear-gradient(90deg, rgba(255, 255, 255, 0.04) 0%, rgba(255, 255, 255, 0) 50%), linear-gradient(90deg, rgba(${theme.primaryRgb}, 0.03) 0%, rgba(${theme.primaryRgb}, 0) 50%)` };
    }
    return { ...baseStyle, background: `linear-gradient(90deg, rgba(255, 255, 255, 0.04) 0%, rgba(255, 255, 255, 0) 50%)` };
  };

  if (showLoader) {
    return <LoadingAnimation theme="primary" subtitle="Создаем будущее вашего бизнеса..." />;
  }

  return (
    <NavigationWithLoader>
      <VideoBackground
        videoSrc={particleSettings.video}
        position={videoPosition}
        volume={volume}
        isPlaying={isPlaying}
      />
      <div className="min-h-screen bg-transparent text-white overflow-x-hidden relative z-10">
        <Navigation scrollToSection={scrollToSection} activeSection={activeSection} sectionTheme={sectionTheme} />
        <HeroSection scrollToSection={scrollToSection} sectionTheme={getSectionTheme('hero')} getBackdropStyle={getBackdropStyle} highlightedService={highlightedService} />
        <ServicesSection sectionTheme={getSectionTheme('services')} getBackdropStyle={getBackdropStyle} onNavigate={onNavigate} highlightedService={highlightedService} />
        <CasesSection sectionTheme={getSectionTheme('cases')} getBackdropStyle={getBackdropStyle} />
        <AboutSection sectionTheme={getSectionTheme('about')} getBackdropStyle={getBackdropStyle} />
        <ContactSection sectionTheme={getSectionTheme('contact')} getBackdropStyle={getBackdropStyle} />
        <FooterSection sectionTheme={getSectionTheme('contact')} getBackdropStyle={getBackdropStyle} />
        <div className="fixed bottom-8 right-5 flex flex-col items-center space-y-4 z-40">
          <VolumeControl isPlaying={isPlaying} volume={volume} onPlayPause={handlePlayPause} onVolumeChange={handleVolumeChange} sectionTheme={sectionTheme} />
          <FloatingActionButton scrollToSection={scrollToSection} />
        </div>
        <div className="fixed top-0 left-0 w-full h-1 bg-gray-800 z-50">
          <div className="h-full transition-all duration-300" style={{ width: `${Math.min(100, (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100)}%`, background: `linear-gradient(90deg, ${sectionTheme.primary}, ${sectionTheme.secondary})` }}></div>
        </div>
      </div>
    </NavigationWithLoader>
  );
};

export default TensisTechWebsite;