import React from 'react';

const LoadingAnimation = ({ 
  title = "TensisTech",
  subtitle = "Загружаем цифровые экосистемы...",
  duration = 2000,
  theme = "primary"
}) => {
  const getThemeStyles = () => {
    switch (theme) {
      case 'service':
        return {
          bgGradient: 'from-gray-900 via-gray-800 to-gray-900',
          spinnerColor: 'border-green-400',
          titleColor: 'text-white',
          subtitleColor: 'text-gray-300'
        };
      default:
        return {
          bgGradient: 'from-gray-900 via-blue-900 to-purple-900',
          spinnerColor: 'border-blue-400',
          titleColor: 'text-white',
          subtitleColor: 'text-gray-300'
        };
    }
  };

  const styles = getThemeStyles();

  return (
    <div className={`fixed inset-0 bg-gradient-to-br ${styles.bgGradient} flex items-center justify-center z-50`}>
      <div className="text-center">
        <div 
          className={`animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 ${styles.spinnerColor} mx-auto mb-4`}
        ></div>
        <h2 className={`text-2xl font-bold ${styles.titleColor} mb-2`}>{title}</h2>
        <p className={styles.subtitleColor}>{subtitle}</p>
      </div>
    </div>
  );
};

export default LoadingAnimation; 