import { useState, useEffect } from 'react';

/**
 * Хук для вычисления адаптивной позиции на основе ширины экрана.
 * @param {Array<number>} basePosition - Базовая позиция [x, y, z].
 * @param {object} coefficients - Коэффициенты для разных размеров экрана.
 * @param {number} coefficients.mobileCoefficient - Коэффициент для мобильных устройств.
 * @param {number} coefficients.desktopCoefficient - Коэффициент для десктопов.
 * @returns {Array<number>} - Вычисленная позиция.
 */
const useResponsivePosition = (basePosition, { mobileCoefficient = 0.15, desktopCoefficient = 0.5 }) => {
  const [position, setPosition] = useState([0, 0, 0]);

  useEffect(() => {
    const calculatePosition = () => {
      const isMobile = window.innerWidth < 768;
      const coefficient = isMobile ? mobileCoefficient : desktopCoefficient;
      
      setPosition([
        basePosition[0] * coefficient,
        basePosition[1] * coefficient,
        basePosition[2] * coefficient,
      ]);
    };

    // Вычисляем позицию при монтировании и при изменении размера окна
    calculatePosition();
    window.addEventListener('resize', calculatePosition);

    // Очистка
    return () => window.removeEventListener('resize', calculatePosition);

  }, [basePosition, mobileCoefficient, desktopCoefficient]);

  return position;
};

export default useResponsivePosition;
