import React, { useState } from 'react';
import { Mail, Phone, Send, MapPin, QrCode } from 'lucide-react';
import QRCode from 'react-qr-code';

const ContactSection = ({ sectionTheme, getBackdropStyle }) => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: '',
    agreePersonalData: false,
    agreeMarketing: false
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [error, setError] = useState(null);

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === 'checkbox' ? checked : value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.agreePersonalData) {
      alert('Необходимо дать согласие на обработку персональных данных');
      return;
    }

    setIsSubmitting(true);
    setError(null);

    const webhookUrl = 'https://tensis.bitrix24.ru/rest/1/mii5j66nc2k5995p/crm.lead.add.json';
    const leadData = {
      fields: {
        TITLE: `Заявка с сайта tensistech.ru от ${formData.name}`,
        NAME: formData.name,
        PHONE: [{ VALUE: formData.phone, VALUE_TYPE: 'WORK' }],
        EMAIL: [{ VALUE: formData.email, VALUE_TYPE: 'WORK' }],
        COMMENTS: formData.message,
        SOURCE_ID: 'WEB',
      },
      params: { REGISTER_SONET_EVENT: 'Y' },
    };

    try {
      const response = await fetch(webhookUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(leadData),
      });

      if (!response.ok) {
        throw new Error('Ошибка при отправке данных. Попробуйте позже.');
      }

      const result = await response.json();
      if (result.error) {
        console.error('Bitrix24 API Error:', result.error_description);
        throw new Error('Ошибка на стороне сервера. Мы уже работаем над этим.');
      }

      localStorage.setItem('contactFormSubmitted', 'true');
      setIsSubmitted(true);

    } catch (err) {
      setError(err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const qrCodeStyle = {
    background: 'white',
    padding: '12px',
    borderRadius: '12px',
    boxShadow: '0 8px 24px rgba(0, 0, 0, 0.2)'
  };

  // Создаем vCard с полной контактной информацией
  const createVCard = () => {
    const vCard = [
      'BEGIN:VCARD',
      'VERSION:3.0',
      'FN:TensisTech',
      'ORG:TensisTech',
      'TEL:+79013889728',
      'EMAIL:info@tensistech.ru',
      'URL:https://tensistech.ru',
      'NOTE:Telegram: @tensistech',
      'ADR:;;ул. Галочкина, д. 18А;г.о. Орехово-Зуевский;Московская область;142605;Россия',
      'END:VCARD'
    ].join('\r\n');
    
    return vCard;
  };

  return (
    <section id="contact" className="py-16 sm:py-20 bg-transparent">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12 sm:mb-16">
          <h2 className={`font-heading text-3xl sm:text-4xl lg:text-5xl font-bold mb-6 sm:mb-8 bg-gradient-to-r ${sectionTheme.textGradient} bg-clip-text text-transparent`}>
            Готовы обсудить ваш проект?
          </h2>
          <p className="font-body text-gray-300 text-base sm:text-lg max-w-2xl mx-auto leading-relaxed">
            Напишите нам, и мы свяжемся с вами в течение 24 часов для обсуждения деталей.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12 max-w-6xl mx-auto">
          {/* Contact Form */}
          <div>
            {isSubmitted ? (
              <div 
                className="p-6 sm:p-8 lg:p-10 text-center"
                style={getBackdropStyle(sectionTheme, 'form')}
              >
                <h3 className={`font-heading text-2xl font-bold mb-4 bg-gradient-to-r ${sectionTheme.textGradient} bg-clip-text text-transparent`}>
                  Спасибо! Ваша заявка принята!
                </h3>
                <p className="font-body text-gray-300 leading-relaxed">
                  Мы свяжемся с вами в ближайшее время.
                </p>
              </div>
            ) : error ? (
              <div 
                className="p-6 sm:p-8 lg:p-10 text-center"
                style={getBackdropStyle(sectionTheme, 'form')}
              >
                <h3 className={`font-heading text-2xl font-bold mb-4 bg-gradient-to-r ${sectionTheme.textGradient} bg-clip-text text-transparent`}>
                  Ошибка отправки
                </h3>
                <p className="font-body text-gray-300 leading-relaxed">
                  К сожалению, при отправке формы произошла ошибка. Пожалуйста, попробуйте еще раз позже или свяжитесь с нами напрямую:
                </p>
                <div className="mt-4">
                  <a href="mailto:info@rubranch.com" className="text-blue-400 hover:underline">info@rubranch.com</a>
                  <span className="text-gray-400 mx-2">|</span>
                  <a href="tel:+74951234567" className="text-blue-400 hover:underline">+7 (495) 123-45-67</a>
                </div>
              </div>
            ) : (
            <form 
              onSubmit={handleSubmit}
              className="p-6 sm:p-8 lg:p-10 space-y-6"
              style={getBackdropStyle(sectionTheme, 'form')}
            >
              <div>
                <label 
                  htmlFor="name" 
                  className="block text-sm font-medium text-gray-300 mb-2"
                >
                  Ваше имя
                </label>
                <input
                  type="text"
                  id="name"
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 bg-gray-800/50 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 transition-all duration-300"
                  style={{
                    '--tw-ring-color': sectionTheme.primary
                  }}
                  placeholder="Как к вам обращаться?"
                  required
                />
              </div>

              <div>
                <label 
                  htmlFor="email" 
                  className="block text-sm font-medium text-gray-300 mb-2"
                >
                  Email
                </label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 bg-gray-800/50 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 transition-all duration-300"
                  style={{
                    '--tw-ring-color': sectionTheme.primary
                  }}
                  placeholder="your@email.com"
                  required
                />
              </div>

              <div>
                <label 
                  htmlFor="message" 
                  className="block text-sm font-medium text-gray-300 mb-2"
                >
                  Расскажите о вашем проекте
                </label>
                <textarea
                  id="message"
                  name="message"
                  rows="6"
                  value={formData.message}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 bg-gray-800/50 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 transition-all duration-300 resize-none"
                  style={{
                    '--tw-ring-color': sectionTheme.primary
                  }}
                  placeholder="Какие задачи хотите решить? Какой у вас бюджет и сроки?"
                  required
                ></textarea>
              </div>

              {/* Согласие на обработку данных */}
              <div className="space-y-3">
                <label className="flex items-start text-sm text-gray-300 cursor-pointer">
                  <input
                    type="checkbox"
                    name="agreePersonalData"
                    checked={formData.agreePersonalData}
                    onChange={handleInputChange}
                    className="mr-3 mt-1 flex-shrink-0"
                    style={{ accentColor: sectionTheme.primary }}
                    required
                  />
                  <span>
                    Нажимая на кнопку, я принимаю{' '}
                    <a href="/legal/user-agreement.html" className="text-blue-400 hover:underline">
                      условия пользовательского соглашения
                    </a>{' '}
                    и даю согласие на обработку моих{' '}
                    <a href="/legal/privacy-policy.html" className="text-blue-400 hover:underline">
                      персональных данных
                    </a> *
                  </span>
                </label>
                <label className="flex items-start text-sm text-gray-300 cursor-pointer">
                  <input
                    type="checkbox"
                    name="agreeMarketing"
                    checked={formData.agreeMarketing}
                    onChange={handleInputChange}
                    className="mr-3 mt-1 flex-shrink-0"
                    style={{ accentColor: sectionTheme.primary }}
                  />
                  <span>
                    Нажимая на кнопку, я даю согласие на получение рекламных материалов
                  </span>
                </label>
              </div>

              <button
                type="submit"
                disabled={!formData.agreePersonalData || isSubmitting}
                className={`w-full px-6 py-4 rounded-lg text-white font-semibold transition-all duration-300 shadow-lg relative overflow-hidden ${
                  (!formData.agreePersonalData || isSubmitting)
                    ? 'opacity-50 cursor-not-allowed'
                    : 'hover:shadow-xl cursor-pointer group/btn'
                }`}
                style={{
                  background: `linear-gradient(135deg, ${sectionTheme.primary}, ${sectionTheme.secondary})`,
                  boxShadow: `0 8px 25px rgba(${sectionTheme.primaryRgb}, 0.4)`
                }}
                onMouseEnter={(e) => {
                  e.target.style.boxShadow = `0 12px 35px rgba(${sectionTheme.primaryRgb}, 0.6)`;
                }}
                onMouseLeave={(e) => {
                  e.target.style.boxShadow = `0 8px 25px rgba(${sectionTheme.primaryRgb}, 0.4)`;
                }}
              >
                <span className="relative z-10">{isSubmitting ? 'Отправка...' : 'Отправить сообщение'}</span>
                {formData.agreePersonalData && !isSubmitting && (
                  <div className="absolute inset-0 bg-gradient-to-r from-white/20 to-transparent transform -skew-x-12 -translate-x-full group-hover/btn:translate-x-full transition-transform duration-700 ease-out"></div>
                )}
              </button>
            </form>
           )}
          </div>

          {/* Contact Information */}
          <div className="space-y-6 sm:space-y-8">
            {/* Быстрые контакты */}
            <div 
              className="hidden lg:block p-6 sm:p-8"
              style={getBackdropStyle(sectionTheme, 'card')}
            >
              <h3 className="font-heading text-xl sm:text-2xl font-bold mb-4 sm:mb-6" style={{ color: sectionTheme.secondary }}>
                Свяжитесь с нами
              </h3>
              <div className="flex gap-6">
                {/* Контакты */}
                <div className="flex-1 space-y-4">
                  <a 
                    href="mailto:info@tensistech.ru"
                    className="flex items-center hover:opacity-80 transition-opacity duration-300 group"
                  >
                    <div 
                      className="w-10 h-10 rounded-full flex items-center justify-center mr-4 flex-shrink-0 group-hover:scale-110 transition-transform duration-300"
                      style={{ backgroundColor: sectionTheme.primary }}
                    >
                      <Mail size={20} className="text-white" />
                    </div>
                    <div>
                      <p className="text-gray-300 text-sm">Email</p>
                      <p className="text-white font-medium text-sm sm:text-base group-hover:underline">info@tensistech.ru</p>
                    </div>
                  </a>
                  <a 
                    href="tel:+79013889728"
                    className="flex items-center hover:opacity-80 transition-opacity duration-300 group"
                  >
                    <div 
                      className="w-10 h-10 rounded-full flex items-center justify-center mr-4 flex-shrink-0 group-hover:scale-110 transition-transform duration-300"
                      style={{ backgroundColor: sectionTheme.accent }}
                    >
                      <Phone size={20} className="text-white" />
                    </div>
                    <div>
                      <p className="text-gray-300 text-sm">Телефон</p>
                      <p className="text-white font-medium text-sm sm:text-base group-hover:underline">+7 (901) 388-97-28</p>
                    </div>
                  </a>
                  <a 
                    href="https://t.me/tensistech"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center hover:opacity-80 transition-opacity duration-300 group"
                  >
                    <div 
                      className="w-10 h-10 rounded-full flex items-center justify-center mr-4 flex-shrink-0 group-hover:scale-110 transition-transform duration-300"
                      style={{ backgroundColor: sectionTheme.secondary }}
                    >
                      <Send size={20} className="text-white" />
                    </div>
                    <div>
                      <p className="text-gray-300 text-sm">Telegram</p>
                      <p className="text-white font-medium text-sm sm:text-base group-hover:underline">@tensistech</p>
                    </div>
                  </a>
                  <div className="flex items-start">
                    <div 
                      className="w-10 h-10 rounded-full flex items-center justify-center mr-4 flex-shrink-0"
                      style={{ backgroundColor: sectionTheme.accent }}
                    >
                      <MapPin size={20} className="text-white" />
                    </div>
                    <div>
                      <p className="text-gray-300 text-sm">Адрес</p>
                      <p className="text-white font-medium text-sm sm:text-base">
                        142605, Московская область,<br/>
                        г. Орехово-Зуево, ул. Галочкина, д. 18А
                      </p>
                    </div>
                  </div>
                </div>
                
                {/* QR-код на одной линии с контактами */}
                <div className="flex-shrink-0">
                  <div className="relative group">
                    <div 
                      className="p-3 rounded-xl cursor-pointer transition-all duration-300 hover:scale-105 flex items-center justify-center"
                      style={{
                        backgroundColor: `rgba(${sectionTheme.primaryRgb}, 0.15)`,
                        border: `2px solid rgba(${sectionTheme.primaryRgb}, 0.3)`
                      }}
                    >
                      <QRCode 
                        value={createVCard()}
                        size={120}
                        style={qrCodeStyle}
                        level="M"
                      />
                    </div>
                    <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-3 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none z-10">
                      <div 
                        className="px-3 py-2 text-sm text-white rounded-lg shadow-lg"
                        style={{ backgroundColor: `rgba(${sectionTheme.primaryRgb}, 0.95)` }}
                      >
                        <div className="flex items-center gap-2">
                          <QrCode size={16} />
                          <span>Сканируйте для добавления контакта</span>
                        </div>
                      </div>
                    </div>
                  </div>
                  <div className="mt-3 text-center">
                    <h4 className="text-sm font-semibold text-white mb-1">QR-код контакта</h4>
                    <p className="text-xs text-gray-400">
                      Добавить в телефонную книгу
                    </p>
                  </div>
                </div>
              </div>
            </div>

            {/* Telegram-канал */}
            <div 
              className="p-6 sm:p-8"
              style={getBackdropStyle(sectionTheme, 'card')}
            >
              <h3 className="font-heading text-xl sm:text-2xl font-bold mb-4" style={{ color: sectionTheme.secondary }}>
                Не теряйте нас из виду
              </h3>
              <p className="text-gray-300 text-sm leading-relaxed mb-6">
                Подпишитесь на наш Telegram-канал, чтобы быть в курсе самых передовых новинок и решений в мире IT и бизнеса.
              </p>
              <a 
                href="https://t.me/tensistech"
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center justify-center w-full px-6 py-3 rounded-lg text-white font-semibold transition-all duration-300 shadow-lg hover:shadow-xl group"
                style={{
                  background: `linear-gradient(135deg, #2AABEE, #229ED9)`,
                  boxShadow: `0 8px 25px rgba(42, 171, 238, 0.4)`
                }}
              >
                <Send size={20} className="mr-3" />
                Перейти в Telegram
              </a>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default ContactSection;