import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { getAssetPath } from '../config';

// ... (хук usePositionTransition остается без изменений) ...
function usePositionTransition(targetPosition, duration = 1200) {
  const [currentPosition, setCurrentPosition] = useState(targetPosition);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const startPositionRef = useRef(new THREE.Vector3(...targetPosition));
  const targetPositionRef = useRef(new THREE.Vector3(...targetPosition));
  const startTimeRef = useRef(0);

  useEffect(() => {
    const newTargetPosition = new THREE.Vector3(...targetPosition);
    if (!targetPositionRef.current.equals(newTargetPosition)) {
      startPositionRef.current.copy(targetPositionRef.current);
      targetPositionRef.current.copy(newTargetPosition);
      startTimeRef.current = performance.now();
      setIsTransitioning(true);
    }
  }, [targetPosition]);

  useFrame(() => {
    if (isTransitioning) {
      const elapsed = performance.now() - startTimeRef.current;
      const progress = Math.min(elapsed / duration, 1);
      const easedProgress = 1 - Math.pow(1 - progress, 3);
      const interpolatedPosition = new THREE.Vector3();
      interpolatedPosition.lerpVectors(startPositionRef.current, targetPositionRef.current, easedProgress);
      setCurrentPosition([interpolatedPosition.x, interpolatedPosition.y, interpolatedPosition.z]);
      if (progress >= 1) {
        setIsTransitioning(false);
      }
    }
  });

  return currentPosition;
}

const vertexShader = `
  uniform float uSize;
  uniform float uTime;
  uniform float uTransitionProgress;
  varying vec2 vUv;

  float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
  }

  vec3 random3d(vec2 st) {
    return vec3(
      random(st + vec2(0.1, 0.2)),
      random(st + vec2(0.3, 0.4)),
      random(st + vec2(0.5, 0.6))
    );
  }

  void main() {
    vUv = uv;

    // The continuous swaying motion
    vec2 center = vec2(0.5);
    vec2 rectHalfSize = vec2(0.4, 0.35);
    vec2 distFromRect = max(abs(uv - center) - rectHalfSize, 0.0);
    float randomnessFactor = length(distFromRect);
    float topEmphasis = pow(uv.y, 1.5);
    float sideEmphasis = pow(abs(uv.x - 0.5) * 2.0, 2.0);
    randomnessFactor *= (1.0 + topEmphasis + sideEmphasis);
    float angle = random(position.xy) * 6.28 + uTime * 0.3;
    vec2 offset = vec2(cos(angle), sin(angle)) * randomnessFactor * 5.0;
    vec3 finalPosition = position + vec3(offset, 0.0);

    // The initial random position for the fly-in effect
    vec3 initialPosition = (random3d(position.xy) - 0.5) * 10.0;

    // Interpolate between initial and final position
    vec3 displacedPosition = mix(initialPosition, finalPosition, uTransitionProgress);

    vec4 modelPosition = modelMatrix * vec4(displacedPosition, 1.0);
    vec4 viewPosition = viewMatrix * modelPosition;
    gl_Position = projectionMatrix * viewPosition;

    float normalizedX = abs(position.x) / 4.5;
    float sizeFactor = 1.0 - smoothstep(0.25, 0.85, normalizedX);
    gl_PointSize = (uSize * sizeFactor) * (1.0 / -viewPosition.z);
  }
`;

const fragmentShader = `
  uniform sampler2D uVideoTexture;
  varying vec2 vUv;
  void main() {
    vec4 videoColor = texture2D(uVideoTexture, vUv);
    if (length(videoColor.rgb) < 0.2) {
      discard;
    }
    gl_FragColor = videoColor;
  }
`;

function VideoAsParticles({ videoTexture, position }) {
  const pointsRef = useRef();
  const currentPosition = usePositionTransition(position);
  const animationState = useRef({
    isAnimating: false,
    startTime: 0,
    duration: 1500, // ms
  });

  const shaderMaterial = useMemo(() => new THREE.ShaderMaterial({
    vertexShader,
    fragmentShader,
    uniforms: {
      uVideoTexture: { value: videoTexture },
      uSize: { value: 75.0 },
      uTime: { value: 0.0 },
      uTransitionProgress: { value: 0.0 },
    },
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  }), [videoTexture]);

  useEffect(() => {
    animationState.current.isAnimating = true;
    animationState.current.startTime = performance.now();
    if (shaderMaterial) {
      shaderMaterial.uniforms.uTransitionProgress.value = 0.0;
    }
  }, [position, shaderMaterial]);

  const [positions, uvs] = useMemo(() => {
    const planeGeometry = new THREE.PlaneGeometry(9, 16, 144, 256);
    return [
      planeGeometry.attributes.position.array,
      planeGeometry.attributes.uv.array,
    ];
  }, []);

  useFrame((state) => {
    if (animationState.current.isAnimating) {
      const elapsed = performance.now() - animationState.current.startTime;
      const rawProgress = Math.min(elapsed / animationState.current.duration, 1);
      const progress = 1 - Math.pow(1 - rawProgress, 3); // easeOutCubic
      shaderMaterial.uniforms.uTransitionProgress.value = progress;

      if (rawProgress >= 1) {
        animationState.current.isAnimating = false;
      }
    }

    if (pointsRef.current) {
      shaderMaterial.uniforms.uTime.value = state.clock.getElapsedTime();
      const swayAngle = Math.PI * 0.05;
      pointsRef.current.rotation.y = Math.sin(state.clock.getElapsedTime() * 0.2) * swayAngle;
      pointsRef.current.position.set(...currentPosition);
    }
  });

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" count={positions.length / 3} array={positions} itemSize={3} />
        <bufferAttribute attach="attributes-uv" count={uvs.length / 2} array={uvs} itemSize={2} />
      </bufferGeometry>
      <primitive object={shaderMaterial} attach="material" />
    </points>
  );
}

// Теперь компонент принимает videoSrc, volume и isPlaying
const VideoBackground = ({ videoSrc, volume, isPlaying, position = [0, 0, 0] }) => {
  const video = useMemo(() => {
    const vid = document.createElement('video');
    vid.crossOrigin = 'Anonymous';
    vid.loop = true;
    vid.playsInline = true;
    vid.preload = 'auto';
    return vid;
  }, []);

  useEffect(() => {
    const newSrc = videoSrc || getAssetPath('video', 'welcome');
    // Преобразуем newSrc в полный URL для корректного сравнения, если это относительный путь
    const absoluteUrl = newSrc.startsWith('/') ? `${window.location.origin}${newSrc}` : newSrc;

    if (video.src !== absoluteUrl) {
      video.src = newSrc;
      video.load();
    }
  }, [video, videoSrc]);

  useEffect(() => {
    if (isPlaying) {
      video.play().catch(err => console.error("Video play failed:", err));
    } else {
      video.pause();
    }
    return () => {
      video.pause();
    };
  }, [video, isPlaying, videoSrc]);

  useEffect(() => {
    const newVolume = Number(volume);
    if (isFinite(newVolume)) {
      video.volume = newVolume;
      video.muted = newVolume === 0;
    } else {
      video.volume = 0;
      video.muted = true;
    }
  }, [video, volume]);

  const videoTexture = useMemo(() => new THREE.VideoTexture(video), [video]);

  return (
    <div className="fixed inset-0 w-full h-full z-0">
      <Canvas
        camera={{ position: [0, 0, 18], fov: 50 }}
        className="w-full h-full"
        style={{ backgroundColor: '#0f172a' }}
      >
        <ambientLight intensity={0.8} />
        <VideoAsParticles videoTexture={videoTexture} position={position} />
      </Canvas>
    </div>
  );
};

export default VideoBackground;
