import React from 'react';
import { ReactComponent as LogoIcon } from '../assets/img/logo.svg';

const Logo = ({ 
  logoText = 'TensisTech', 
  sectionTheme, 
  size = 'normal',
  className = '' 
}) => {
  const isRussian = logoText === 'ТензисТех';
  
  // Size variants
  const sizeClasses = {
    normal: {
      main: 'text-xl sm:text-2xl',
      tech: 'text-lg sm:text-xl',
      icon: 'w-8 h-8 sm:w-10 sm:h-10'
    },
    large: {
      main: 'text-2xl sm:text-3xl',
      tech: 'text-xl sm:text-2xl',
      icon: 'w-10 h-10 sm:w-12 sm:h-12'
    },
    small: {
      main: 'text-lg sm:text-xl',
      tech: 'text-base sm:text-lg',
      icon: 'w-6 h-6 sm:w-8 sm:h-8'
    }
  };

  const LogoContent = ({ children }) => (
    <div className={`flex items-center gap-2 ${className}`}>
      <div className={`${sizeClasses[size].icon} flex-shrink-0`}>
        <LogoIcon 
          className="w-full h-full"
          style={{
            filter: `drop-shadow(0 0 20px rgba(${sectionTheme.primaryRgb}, 0.5)) drop-shadow(0 0 40px rgba(${sectionTheme.primaryRgb}, 0.3)) drop-shadow(0 0 8px rgba(${sectionTheme.primaryRgb}, 0.3))`,
            color: sectionTheme.primary,
            fill: sectionTheme.primary
          }}
        />
      </div>
      <div className="flex items-baseline">
        {children}
      </div>
    </div>
  );

  if (isRussian) {
    return (
      <LogoContent>
        <span 
          className={`font-heading font-black tracking-wider ${sizeClasses[size].main} uppercase`}
          style={{
            color: sectionTheme.primary,
            textShadow: `0 0 20px rgba(${sectionTheme.primaryRgb}, 0.5), 0 0 40px rgba(${sectionTheme.primaryRgb}, 0.3)`,
            filter: `drop-shadow(0 0 8px rgba(${sectionTheme.primaryRgb}, 0.3))`
          }}
        >
          ТЕНЗИС
        </span>
        <span 
          className={`font-heading font-thin ${sizeClasses[size].tech} ml-0.5 tracking-widest`}
          style={{
            color: sectionTheme.secondary,
            textShadow: `0 0 15px rgba(${sectionTheme.primaryRgb}, 0.3)`,
            opacity: 0.9
          }}
        >
          ТЕХ
        </span>
      </LogoContent>
    );
  } else {
    return (
      <LogoContent>
        <span 
          className={`font-heading font-black tracking-wider ${sizeClasses[size].main} uppercase`}
          style={{
            color: sectionTheme.primary,
            textShadow: `0 0 20px rgba(${sectionTheme.primaryRgb}, 0.5), 0 0 40px rgba(${sectionTheme.primaryRgb}, 0.3)`,
            filter: `drop-shadow(0 0 8px rgba(${sectionTheme.primaryRgb}, 0.3))`
          }}
        >
          TENSIS
        </span>
        <span 
          className={`font-heading font-thin ${sizeClasses[size].tech} ml-0.5 tracking-widest`}
          style={{
            color: sectionTheme.secondary,
            textShadow: `0 0 15px rgba(${sectionTheme.primaryRgb}, 0.3)`,
            opacity: 0.9
          }}
        >
          TECH
        </span>
      </LogoContent>
    );
  }
};

export default Logo; 